style.css:
@-moz-document domain("ruliweb.com") {
#main .adrr, .nbp_container_4, #ad_main_ti_new, #ad_main_top_05, #ti3, div[data-name='cfa5'] {
    display: none !important;
}
#main_top, #subtop, #best, #userboard, #family_site, #news > .row {
    margin-top: 82px !important;
}
.side_wrapper {
    margin-top: 72px;
    height: calc(100% - 72px);
}
 .right_side_wrapper {
	top: 72px !important;
}

#header {
    position: fixed;
    width: 100%;
}
#board_top .best_list {
    width: 100% !important;
    box-sizing: border-box;
}
/* 프로필 */
 #board_read .board_main .board_main_top .user_view {
    width: 100% !important;
}
#board_read .board_main .board_main_top .user_view .type_i, #board_read .board_main .board_main_top .user_view .type_g, #board_read .board_main .board_main_top .user_view .type_f {
    margin : 15px !important;
}
#board_read .board_main .board_main_top .user_view .type_i {
    width: 200px;
    height: 200px;
}
#board_read .board_main .board_main_top .user_view .type_i img {
    width: 100%;
    height: 100%;
}
#board_read .board_main .board_main_top .user_view .user_info_wrapper {
    width: 480px;
    margin-top: 15px;
}
#board_read .board_main .board_main_top .user_view .user_info .btn_wrapper a {
    width: 65px;
}
#board_read .board_main .board_main_top .user_view .user_info p .exp_bar {
    width: 330px;
    height: 14px;
}
#board_read .board_main .board_main_top .user_view .user_info p .exp_text {
    border: 0px;
}
#board_read .board_main .board_main_top .user_view .member_reward_wrapper .member_icon {
    margin-top: 15px;
}
#board_read .board_main .board_main_top .user_view .member_reward_wrapper {
    width: 310px;
}
#board_read .board_main .board_main_top .user_view .member_reward_wrapper .member_achievement .exp_bar {
    width: 18px;
    height: 66px;
    margin-top: 5px;
    margin-right: 8px;
}
}
